  ('ld_002', 'ws_1sv', 'Corey Beatson', '@coreybeats', 'https://instagram.com/coreybeats', 'corey@example.com', 'Instagram', 'Competitor account commenters', 'Producer,Collab', 'Good fit for producer collaboration night.', 'Replied', 'Houston', 'Producer. Keys, drums, and sample flips.', '2026-05-07', 'tm_manager', 'public_profile'),
