INSERT INTO campaigns (id, workspace_id, name, campaign_type, audience, message_step_1, follow_up_1, follow_up_2, wait_time_hours, stop_condition, daily_limit, is_running) VALUES
  ('cmp_001', 'ws_1sv', 'Houston recording studio tour', 'Studio tour invite', 'Houston artists and creators', 'Hey {first_name}, saw you through {source}. Your sound feels like it would fit the 1 Soundvibe rooms. Want me to send a quick studio tour link?', 'Just circling back, {first_name}. We have a few tour slots this week if you want to see the space before your next session.', 'No pressure — should I close the loop or keep you posted when tour times open up?', 72, 'Stop sequence immediately when the lead replies, opts out, or books.', 35, 1),
  ('cmp_002', 'ws_1sv', 'R&B artist session invite', 'Recording session offer', 'R&B singers and songwriters', 'Peace {first_name}, your vocals caught my attention. 1 Soundvibe has a clean setup for R&B sessions — want details on booking a session?', 'We can help with tracking, vocal production, and a comfortable room. Want me to send the booking link?', 'Last follow-up from me — if now is not the right time, I can check back later.', 72, 'Stop when the artist replies, declines, says stop, or books.', 25, 1),
  ('cmp_003', 'ws_1sv', 'Producer collaboration', 'Producer collaboration invite', 'Producers and beat makers', 'Yo {first_name}, I saw your producer work from {source}. We are connecting serious producers with artists at 1 Soundvibe — open to a collab intro?', 'Would a producer night or artist writing session be useful for you?', 'If you want, I can send the next invite when we lock the room schedule.', 96, 'Stop when the lead replies or opts out.', 20, 1),
  ('cmp_004', 'ws_1sv', 'Vibe Check Thursday invite', 'Vibe Check event invite', 'Performers and fans', 'Hey {first_name}, we host Vibe Check Thursday at 1 Soundvibe. Your energy looks like a fit — want the performer details?', 'Spots are limited and curated. Want me to send the signup link?', 'Should I keep you on the list for future Vibe Check dates?', 48, 'Stop when the lead replies, signs up, or declines.', 30, 1),
  ('cmp_005', 'ws_1sv', 'Podcast room booking', 'Podcast studio invite', 'Podcast hosts and video creators', 'Hey {first_name}, noticed your podcast work. 1 Soundvibe has a private podcast room if you ever need a clean recording setup — want the booking link?', 'We can support solo episodes, interviews, and short-form clips. Want to see times?', 'No worries if not — I can send details whenever you are ready.', 72, 'Stop when booked, replied, or opted out.', 25, 1),
  ('cmp_006', 'ws_1sv', 'Membership offer', 'Membership offer', 'Recurring creators', 'Hey {first_name}, if you are recording often, 1 Soundvibe memberships can make sessions simpler. Want the membership options?', 'Membership can help with room access, planning, and consistent creative workflow.', 'Should I send a quick breakdown or close this out?', 120, 'Stop when the lead replies, requests pricing, joins, or opts out.', 15, 1);
